/**
 * `media/provenance.json` — where each media file in an export came from.
 *
 * An exported pwpack can carry media (images and other files under `media/`).
 * The bytes alone do not say whether a file was generated by a model, uploaded
 * by a person, or provided with the pack, nor under which licence it may be
 * reused. This file records that, one entry per media file, so whoever opens
 * the export can answer those questions without the system that made it.
 *
 * Entries are keyed by `path` (relative to the export root, e.g.
 * `media/hero.webp`); a path appears at most once. `hash` identifies the bytes
 * the entry describes, so a replaced file is visibly a different file.
 *
 * @module @pwfabric/contracts/fabric/media-provenance
 */

import { z } from 'zod'

// ============================================================
// TYPES
// ============================================================

/** How a media file came to exist. */
export const MEDIA_PROVENANCE_SOURCES = ['generated', 'uploaded', 'provided'] as const

/**
 * - `generated` — produced by a model (see `model`).
 * - `uploaded` — added by a person.
 * - `provided` — shipped with a pack or supplied by the host.
 */
export type MediaProvenanceSource = (typeof MEDIA_PROVENANCE_SOURCES)[number]

/** One media file's provenance. */
export interface MediaProvenanceEntry {
  /** Path of the file relative to the export root, e.g. `media/hero.webp`. */
  readonly path: string
  /** Content hash of the file's bytes, e.g. `sha256:<hex>`. */
  readonly hash: string
  readonly source: MediaProvenanceSource
  /** The model that generated the file. Meaningful for `source: 'generated'`. */
  readonly model?: string
  /** When the file was created, as an ISO 8601 date-time. */
  readonly createdAt: string
  /** Licence the file may be reused under (an SPDX id or free text). */
  readonly license?: string
  /** URL the file was taken from, when it has one. */
  readonly origin?: string
}

/** The whole `media/provenance.json` document. */
export interface MediaProvenance {
  /**
   * Version of this file's contract, `MAJOR.MINOR`. Absent means the first,
   * pre-versioned form.
   */
  readonly formatVersion?: string
  readonly items: readonly MediaProvenanceEntry[]
}

// ============================================================
// SCHEMAS
// ============================================================

export const MediaProvenanceEntrySchema = z.object({
  path: z.string().min(1),
  hash: z.string().min(1),
  source: z.enum(MEDIA_PROVENANCE_SOURCES),
  model: z.string().min(1).optional(),
  createdAt: z.string().datetime({ offset: true }),
  license: z.string().min(1).optional(),
  origin: z.string().url().optional(),
})

export const MediaProvenanceSchema = z
  .object({
    formatVersion: z
      .string()
      .regex(/^\d+\.\d+$/, 'formatVersion must be MAJOR.MINOR, e.g. "1.0"')
      .optional(),
    items: z.array(MediaProvenanceEntrySchema),
  })
  .superRefine((doc, ctx) => {
    const seen = new Set<string>()
    doc.items.forEach((item, i) => {
      if (seen.has(item.path)) {
        ctx.addIssue({
          code: z.ZodIssueCode.custom,
          path: ['items', i, 'path'],
          message: `media provenance lists "${item.path}" more than once`,
        })
      }
      seen.add(item.path)
    })
  })

// ============================================================
// HELPERS
// ============================================================

export type MediaProvenanceValidation =
  { readonly ok: true; readonly value: MediaProvenance } | { readonly ok: false; readonly issues: readonly string[] }

/** Parse a `media/provenance.json` document. Throws a `ZodError` when it is not valid. */
export function parseMediaProvenance(input: unknown): MediaProvenance {
  // Cast: zod's optional output is `T | undefined`; the contract type is
  // `T`-or-absent (exactOptionalPropertyTypes). Same shape.
  return MediaProvenanceSchema.parse(input) as MediaProvenance
}

/** Validate a `media/provenance.json` document without throwing. Issues read `path: message`. */
export function safeParseMediaProvenance(input: unknown): MediaProvenanceValidation {
  const parsed = MediaProvenanceSchema.safeParse(input)
  if (parsed.success) return { ok: true, value: parsed.data as MediaProvenance }
  return {
    ok: false,
    issues: parsed.error.issues.map((i) => (i.path.length ? `${i.path.join('.')}: ${i.message}` : i.message)),
  }
}
